-- ============================================================
--  给数据库插入 2 条请假记录（带示例证明图片）
--  用法： mysql -u root -p --default-character-set=utf8mb4 class2603 < seed_leave.sql
--         （执行后按提示输入数据库密码，不要把密码写在命令里）
--  说明： 图片用 FROM_BASE64 内嵌在 SQL 里，不需要单独传图片文件
--         重复执行会先删掉这 2 条演示数据再重新插入，不会产生重复
-- ============================================================
USE class2603;

-- 先清理可能存在的旧测试数据（按学号+理由精确匹配，不误伤其他记录）
DELETE FROM CLASS_FUNDS2603
 WHERE student_id IN (20260302, 20260305)
   AND six_day_reason LIKE '%[演示数据]%';

INSERT INTO CLASS_FUNDS2603 (student_id, name, picture, six_day_reason, `time`)
VALUES
(
    20260302,
    '王芳',
    FROM_BASE64(''),
    '[演示数据] 发热 38.6℃，校医院诊断为上呼吸道感染，建议居家休息三天，已附诊断证明。',
    '2026-10-20'
),
(
    20260305,
    '陈静',
    FROM_BASE64(''),
    '[演示数据] 代表学校参加市青少年科技创新大赛，需外出比赛一天，已附教务处通知。',
    '2026-10-22'
);

-- 查看结果
SELECT id, student_id, name, LEFT(six_day_reason, 24) AS 理由, `time`,
       LENGTH(picture) AS 图片字节
  FROM CLASS_FUNDS2603
 ORDER BY id;

-- 抽查：请假记录数 / 涉及学生数
SELECT COUNT(*) AS 请假总条数, COUNT(DISTINCT student_id) AS 请假人数
  FROM CLASS_FUNDS2603;
